public class DynamicDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        // 只返回 ThreadLocal 里的 key，不写任何 if/switch 分支
        return DataSourceContextHolder.get();
    }
}

public static <T> T executeWithDataSource(String dsKey, Supplier<T> action) {
    String previous = DataSourceContextHolder.get();
    DataSourceContextHolder.set(dsKey);
    try {
        return action.get();
    } finally {
        // 必须恢复旧值而不是 clear()：嵌套调用返回后外层还要用原来的库
        DataSourceContextHolder.set(previous);
    }
}

@Bean(name = "oracleDataSource")
@ConfigurationProperties(prefix = "spring.datasource.oracle")
public DruidDataSource oracleDataSource() {
    DruidDataSource ds = new DruidDataSource();
    ds.setInitialSize(5);
    ds.setMinIdle(5);
    ds.setMaxActive(50);
    ds.setMaxWait(60_000);
    // 校验连接可用性：Oracle 侧有防火墙空闲断连
    ds.setValidationQuery("SELECT 1 FROM DUAL");
    ds.setTestWhileIdle(true);
    ds.setTimeBetweenEvictionRunsMillis(60_000);
    return ds;
}
